<template><h2>Agents</h2><el-table :data="items"><el-table-column prop="name" label="Name"/><el-table-column prop="id" label="ID"/><el-table-column prop="enabled" label="Enabled"/><el-table-column label="Actions"><template #default="scope"><el-button link type="primary" @click="$router.push(`/agents/${scope.row.id}`)">Details</el-button></template></el-table-column></el-table></template>
<script setup lang="ts">import {ref,onMounted} from 'vue'; import {getAgents, type Agent} from '../api/client'; const items=ref<Agent[]>([]); onMounted(async()=>{items.value=(await getAgents()).items})</script>
